-- Pending local migration generated by Supabase CLI; NOT applied to staging.
-- No live schema changes have been made. Apply transactionally after local security tests.
begin;
-- Historical migrations created a deny policy but depended on a dashboard
-- event trigger to enable RLS. Fresh installs must enforce this explicitly.
alter table public.project_product_instances enable row level security;
revoke all on public.project_product_instances from anon, authenticated;
revoke insert, delete on public.profiles from authenticated, anon;
revoke update on public.profiles from authenticated;
grant update (full_name, avatar_url, phone, company_name, user_type, onboarding_completed)
  on public.profiles to authenticated;
drop policy if exists profiles_admin_insert on public.profiles;
drop policy if exists profiles_admin_delete on public.profiles;
alter policy profiles_authenticated_read on public.profiles using (
  id = (select auth.uid()) or (select public.get_my_role()) in ('admin','super_admin')
);
-- Audit claims can only be appended by trusted functions/triggers in the same transaction.
revoke all on function public.admin_log_action(text,text,uuid,jsonb) from public, anon, authenticated;
create or replace function public.admin_set_user_role(target_user_id uuid, new_role text)
returns void
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  caller_role text;
  target_role text;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  -- Authorization roles are intentionally separate from user_type segmentation.
  -- Designers, offices, contractors, suppliers, etc. remain role=user and are
  -- classified through profiles.user_type.
  if new_role is null or new_role not in ('user','reviewer','admin','super_admin') then
    raise exception 'Invalid authorization role';
  end if;

  if target_user_id = auth.uid() then
    raise exception 'Cannot change own role';
  end if;

  -- Lock before authorization and reads: concurrent demotions cannot authorize on stale roles.
  lock table public.profiles in share row exclusive mode;
  select role into caller_role from public.profiles where id=auth.uid() for update;
  caller_role := coalesce(caller_role, 'user');
  if caller_role not in ('admin','super_admin') then
    raise exception 'Permission denied';
  end if;

  select role into target_role
  from public.profiles
  where id = target_user_id;

  if target_role is null then
    raise exception 'Target user not found';
  end if;

  if caller_role = 'admin'
     and (new_role in ('admin','super_admin') or target_role in ('admin','super_admin')) then
    raise exception 'Only super_admin may manage admin roles';
  end if;

  if target_role = 'super_admin' and new_role <> 'super_admin'
     and (select count(*) from public.profiles where role = 'super_admin') <= 1 then
    raise exception 'Cannot remove the last super_admin';
  end if;

  update public.profiles
  set role = new_role
  where id = target_user_id;

  perform public.admin_log_action(
    'user.role_change',
    'user',
    target_user_id,
    jsonb_build_object('old_role', target_role, 'new_role', new_role)
  );
end;
$function$;

revoke all on function public.admin_set_user_role(uuid,text) from public, anon;
grant execute on function public.admin_set_user_role(uuid,text) to authenticated;

create or replace function public.audit_catalog_mutation() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if auth.uid() is not null then
    if tg_op = 'DELETE' then v_id := old.id; else v_id := new.id; end if;
    insert into public.admin_audit_log(actor_user_id, action, target_type, target_id, metadata)
    values(auth.uid(), tg_table_name || '.' || lower(tg_op), tg_table_name, v_id,
      jsonb_build_object('operation', lower(tg_op)));
  end if;
  return null;
end $$;
revoke all on function public.audit_catalog_mutation() from public, anon, authenticated;
do $$ declare t text; begin
  foreach t in array array['products','suppliers','categories','subcategories',
    'product_files','product_images','product_specifications'] loop
    execute format('create trigger audit_catalog_mutation after insert or update or delete on public.%I for each row execute function public.audit_catalog_mutation()', t);
  end loop;
end $$;
create or replace function public.admin_save_mvp_product(
  p_product_id uuid default null,
  p_payload jsonb default '{}'::jsonb
)
returns public.products
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  v_existing public.products%rowtype;
  v_row public.products%rowtype;
  v_name_ar text;
  v_name_en text;
  v_slug text;
  v_category_id uuid;
  v_subcategory_id uuid;
  v_supplier_id uuid;
  v_price numeric;
  v_currency text;
  v_supplier_url text;
  v_source_url text;
  v_rights boolean;
  v_state text;
  v_status text;
  v_visibility text;
  v_approved_by uuid;
  v_approved_at timestamptz;
begin
  if public.get_my_role() not in ('admin','super_admin') then raise exception 'Admin access required'; end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then raise exception 'Invalid payload'; end if;

  if p_product_id is not null then
    select * into v_existing from public.products where id = p_product_id for update;
    if not found then raise exception 'Product not found'; end if;
  end if;

  v_name_ar := case when p_payload ? 'product_name_ar' then nullif(trim(p_payload->>'product_name_ar'),'') else v_existing.product_name_ar end;
  v_name_en := case when p_payload ? 'product_name_en' then nullif(trim(p_payload->>'product_name_en'),'') else v_existing.product_name_en end;
  if v_name_ar is null or v_name_en is null then raise exception 'Arabic and English product names are required'; end if;
  if length(v_name_ar)>250 or length(v_name_en)>250 then raise exception 'Product name too long'; end if;

  v_category_id := case when p_payload ? 'category_id' then nullif(p_payload->>'category_id','')::uuid else v_existing.category_id end;
  v_subcategory_id := case when p_payload ? 'subcategory_id' then nullif(p_payload->>'subcategory_id','')::uuid else v_existing.subcategory_id end;
  v_supplier_id := case when p_payload ? 'supplier_id' then nullif(p_payload->>'supplier_id','')::uuid else v_existing.supplier_id end;
  if v_category_id is not null and not exists(select 1 from public.categories c where c.id=v_category_id) then raise exception 'Invalid category'; end if;
  if v_subcategory_id is not null and not exists(select 1 from public.subcategories s where s.id=v_subcategory_id and s.category_id=v_category_id) then raise exception 'Invalid subcategory'; end if;
  if v_supplier_id is not null and not exists(select 1 from public.suppliers s where s.id=v_supplier_id) then raise exception 'Invalid supplier'; end if;

  if p_payload ? 'slug' then
    v_slug := nullif(lower(trim(p_payload->>'slug')), '');
  else
    v_slug := v_existing.slug;
    if v_slug is null then v_slug := nullif(trim(both '-' from lower(regexp_replace(v_name_en,'[^a-zA-Z0-9]+','-','g'))),''); end if;
  end if;
  if v_slug is not null and (length(v_slug)>160 or v_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$') then raise exception 'Invalid product slug'; end if;
  if v_slug is not null and exists(select 1 from public.products p where p.slug=v_slug and p.id is distinct from p_product_id) then raise exception 'Product slug already exists'; end if;

  v_price := case when p_payload ? 'price' then nullif(p_payload->>'price','')::numeric else v_existing.price end;
  if v_price is not null and v_price < 0 then raise exception 'Price cannot be negative'; end if;
  v_currency := upper(case when p_payload ? 'currency' then coalesce(nullif(trim(p_payload->>'currency'),''),'SAR') else coalesce(v_existing.currency,'SAR') end);
  if v_currency !~ '^[A-Z]{3}$' then raise exception 'Invalid currency'; end if;

  v_supplier_url := case when p_payload ? 'supplier_product_url' then nullif(trim(p_payload->>'supplier_product_url'),'') else v_existing.supplier_product_url end;
  v_source_url := case when p_payload ? 'source_url' then nullif(trim(p_payload->>'source_url'),'') else v_existing.source_url end;
  if v_supplier_url is not null and (length(v_supplier_url)>2048 or v_supplier_url !~* '^https?://') then raise exception 'Supplier product URL must use http or https'; end if;
  if v_source_url is not null and (length(v_source_url)>2048 or v_source_url !~* '^https?://') then raise exception 'Source URL must use http or https'; end if;

  v_rights := case when p_payload ? 'rights_confirmed' then coalesce((p_payload->>'rights_confirmed')::boolean,false) else coalesce(v_existing.rights_confirmed,false) end;
  v_state := case when p_payload ? 'publication_state' then lower(coalesce(nullif(p_payload->>'publication_state',''),'draft')) else null end;
  if v_state is null then
    if p_product_id is null then v_state := 'draft';
    elsif v_existing.status='approved' and v_existing.visibility='public' then v_state := 'published';
    elsif v_existing.status='archived' then v_state := 'archived';
    else v_state := 'draft'; end if;
  end if;
  if v_state not in ('draft','published','archived') then raise exception 'Invalid publication state'; end if;

  if v_state='published' then
    if not exists(select 1 from public.categories c where c.id=v_category_id and c.is_active) then raise exception 'Published product requires an active category'; end if;
    if v_subcategory_id is not null and not exists(select 1 from public.subcategories c where c.id=v_subcategory_id and c.is_active) then raise exception 'Published product requires an active subcategory'; end if;
    if v_category_id is null then raise exception 'Published product requires a category'; end if;
    if v_supplier_id is null then raise exception 'Published product requires a supplier'; end if;
    if not exists(select 1 from public.suppliers s where s.id=v_supplier_id and s.is_published=true) then raise exception 'Supplier window must be published first'; end if;
    if v_slug is null then raise exception 'Published product requires a slug'; end if;
    if not v_rights then raise exception 'Rights confirmation is required before publishing'; end if;
    v_status := 'approved'; v_visibility := 'public'; v_approved_by := auth.uid(); v_approved_at := now();
  elsif v_state='archived' then
    v_status := 'archived'; v_visibility := 'private'; v_approved_by := v_existing.approved_by; v_approved_at := v_existing.approved_at;
  else
    v_status := 'draft'; v_visibility := 'private'; v_approved_by := null; v_approved_at := null;
  end if;

  if p_product_id is null then
    insert into public.products(
      product_name_ar, product_name_en, short_description_ar, short_description_en,
      full_description_ar, full_description_en, category_id, subcategory_id, product_type,
      supplier_id, brand_name, model_number, country_of_origin, unit,
      status, verification_status, visibility, is_free, price, currency,
      source_url, rights_confirmed, created_by, approved_by, approved_at, slug,
      supplier_product_url, is_featured, sort_order, license_download
    ) values (
      v_name_ar, v_name_en, nullif(trim(p_payload->>'short_description_ar'),''), nullif(trim(p_payload->>'short_description_en'),''),
      nullif(trim(p_payload->>'full_description_ar'),''), nullif(trim(p_payload->>'full_description_en'),''),
      v_category_id, v_subcategory_id, nullif(trim(p_payload->>'product_type'),''), v_supplier_id,
      nullif(trim(p_payload->>'brand_name'),''), nullif(trim(p_payload->>'model_number'),''),
      nullif(trim(p_payload->>'country_of_origin'),''), nullif(trim(p_payload->>'unit'),''),
      v_status, 'unverified', v_visibility, true, v_price, v_currency,
      v_source_url, v_rights, auth.uid(), v_approved_by, v_approved_at, v_slug,
      v_supplier_url, coalesce((p_payload->>'is_featured')::boolean,false), coalesce(nullif(p_payload->>'sort_order','')::int,0), coalesce((p_payload->>'license_download')::boolean,false)
    ) returning * into v_row;
  else
    update public.products set
      product_name_ar=v_name_ar,
      product_name_en=v_name_en,
      short_description_ar=case when p_payload ? 'short_description_ar' then nullif(trim(p_payload->>'short_description_ar'),'') else short_description_ar end,
      short_description_en=case when p_payload ? 'short_description_en' then nullif(trim(p_payload->>'short_description_en'),'') else short_description_en end,
      full_description_ar=case when p_payload ? 'full_description_ar' then nullif(trim(p_payload->>'full_description_ar'),'') else full_description_ar end,
      full_description_en=case when p_payload ? 'full_description_en' then nullif(trim(p_payload->>'full_description_en'),'') else full_description_en end,
      category_id=v_category_id,
      subcategory_id=v_subcategory_id,
      product_type=case when p_payload ? 'product_type' then nullif(trim(p_payload->>'product_type'),'') else product_type end,
      supplier_id=v_supplier_id,
      brand_name=case when p_payload ? 'brand_name' then nullif(trim(p_payload->>'brand_name'),'') else brand_name end,
      model_number=case when p_payload ? 'model_number' then nullif(trim(p_payload->>'model_number'),'') else model_number end,
      country_of_origin=case when p_payload ? 'country_of_origin' then nullif(trim(p_payload->>'country_of_origin'),'') else country_of_origin end,
      unit=case when p_payload ? 'unit' then nullif(trim(p_payload->>'unit'),'') else unit end,
      status=v_status,
      visibility=v_visibility,
      is_free=true,
      price=v_price,
      currency=v_currency,
      source_url=v_source_url,
      rights_confirmed=v_rights,
      license_download=case when p_payload ? 'license_download' then coalesce((p_payload->>'license_download')::boolean,false) else license_download end,
      approved_by=v_approved_by,
      approved_at=v_approved_at,
      slug=v_slug,
      supplier_product_url=v_supplier_url,
      is_featured=case when p_payload ? 'is_featured' then coalesce((p_payload->>'is_featured')::boolean,false) else is_featured end,
      sort_order=case when p_payload ? 'sort_order' then coalesce(nullif(p_payload->>'sort_order','')::int,0) else sort_order end
    where id=p_product_id returning * into v_row;
  end if;
  return v_row;
end;
$function$;


alter table public.products alter column license_download set default false;
alter table public.product_specifications add constraint launch_specification_type
  check (data_type in ('text','number','boolean','date','url')) not valid;

-- Publication requirements apply to direct table writes as well as RPCs.
create function public.enforce_launch_publication() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.status='approved' and new.visibility='public' then
    if new.rights_confirmed is not true or nullif(btrim(new.slug),'') is null then
      raise exception 'Published product requires confirmed rights and a slug';
    end if;
    if not exists(select 1 from public.categories where id=new.category_id and is_active) then
      raise exception 'Published product requires an active category';
    end if;
    if new.subcategory_id is not null and not exists(select 1 from public.subcategories where id=new.subcategory_id and category_id=new.category_id and is_active) then
      raise exception 'Published product requires a matching active subcategory';
    end if;
    if not exists(select 1 from public.suppliers where id=new.supplier_id and is_published and slug is not null) then
      raise exception 'Published product requires a published supplier';
    end if;
  end if;
  return new;
end $$;
revoke all on function public.enforce_launch_publication() from public, anon, authenticated;
create trigger enforce_launch_publication before insert or update of status,visibility,rights_confirmed,slug,category_id,subcategory_id,supplier_id
on public.products for each row execute function public.enforce_launch_publication();

-- One RPC transaction: any invalid specification rolls back product and audit changes too.
create function public.admin_save_mvp_product_bundle(p_product_id uuid, p_payload jsonb, p_items jsonb)
returns public.products language plpgsql security definer set search_path = public as $$
declare v_row public.products;
begin
  if auth.uid() is null or public.get_my_role() not in ('admin','super_admin') then
    raise exception 'Admin access required';
  end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' then raise exception 'Specifications must be an array'; end if;
  if jsonb_array_length(p_items) > 100 then raise exception 'Too many specifications'; end if;
  if exists(select from jsonb_array_elements(p_items) i where jsonb_typeof(i) <> 'object'
    or coalesce(i->>'data_type','text') not in ('text','number','boolean','date','url')
    or nullif(btrim(i->>'value'),'') is null
    or coalesce(nullif(btrim(i->>'specification_name_ar'),''),nullif(btrim(i->>'specification_name_en'),'')) is null)
  then raise exception 'Every specification requires a name, value and supported data type'; end if;
  v_row := public.admin_save_mvp_product(p_product_id, p_payload);
  perform public.admin_replace_mvp_product_specifications(v_row.id, p_items);
  return v_row;
end $$;
revoke all on function public.admin_save_mvp_product_bundle(uuid,jsonb,jsonb) from public, anon;
grant execute on function public.admin_save_mvp_product_bundle(uuid,jsonb,jsonb) to authenticated;

-- Invoker ingestion returns its preallocated UUID without requiring SELECT of private events.
create or replace function public.record_usage_event(
  p_event_name text, p_product_id uuid default null, p_supplier_id uuid default null,
  p_session_id uuid default null, p_metadata jsonb default '{}'::jsonb
) returns uuid language plpgsql security invoker set search_path = public as $$
declare v_event_id uuid := gen_random_uuid();
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  insert into public.usage_events(id,event_name,product_id,supplier_id,session_id,metadata)
  values(v_event_id,p_event_name,p_product_id,p_supplier_id,p_session_id,coalesce(p_metadata,'{}'::jsonb));
  return v_event_id;
end $$;
create or replace function public.set_usage_event_user_snapshot()
returns trigger
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_uid uuid := auth.uid();
  v_file_id_text text;
  v_category_id_text text;
  v_supplier_id_text text;
  v_expected_file_type text;
begin
  if v_uid is null then
    raise exception 'Authentication required';
  end if;

  -- Serialize ingestion per identity before counting; client timestamps are never trusted.
  perform pg_advisory_xact_lock(hashtextextended('usage:' || v_uid::text, 0));
  new.created_at := clock_timestamp();

  if new.event_name not in (
    'session_start', 'catalog_view', 'product_view', 'supplier_view', 'search',
    'filter', 'block_download', 'datasheet_download', 'signup_complete', 'login'
  ) then
    raise exception 'Unsupported event';
  end if;

  new.metadata := coalesce(new.metadata, '{}'::jsonb);
  if jsonb_typeof(new.metadata) <> 'object' then
    raise exception 'Metadata must be an object';
  end if;

  select coalesce(jsonb_object_agg(entry.key, entry.value), '{}'::jsonb)
    into new.metadata
  from jsonb_each(new.metadata) as entry
  where entry.key = any (array['page', 'category_id', 'supplier_id', 'file_id']::text[]);

  if new.metadata ? 'page' and (
    jsonb_typeof(new.metadata->'page') <> 'string'
    or new.metadata->>'page' !~ '^[a-zA-Z0-9_-]{1,64}$'
  ) then
    raise exception 'Invalid page metadata';
  end if;

  if octet_length(new.metadata::text) > 8192 then
    raise exception 'Metadata too large';
  end if;

  if (
    select count(*)
    from public.usage_events e
    where e.user_id = v_uid
      and e.created_at >= now() - interval '1 minute'
  ) >= 120 then
    raise exception 'Event rate limit exceeded';
  end if;

  if new.product_id is not null and not exists (
    select 1 from public.products p
    where p.id = new.product_id
      and p.status = 'approved'
      and p.visibility = 'public'
  ) then
    raise exception 'Invalid product';
  end if;

  if new.supplier_id is not null and not exists (
    select 1 from public.suppliers s
    where s.id = new.supplier_id
      and s.is_published = true
  ) then
    raise exception 'Invalid supplier';
  end if;

  if new.metadata ? 'category_id' then
    v_category_id_text := nullif(trim(new.metadata->>'category_id'), '');
    if v_category_id_text is null
       or v_category_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or not exists (
         select 1 from public.categories c
         where c.id = v_category_id_text::uuid
           and c.is_active = true
       ) then
      raise exception 'Invalid category metadata';
    end if;
  end if;

  if new.metadata ? 'supplier_id' then
    v_supplier_id_text := nullif(trim(new.metadata->>'supplier_id'), '');
    if v_supplier_id_text is null
       or v_supplier_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or new.supplier_id is null
       or new.supplier_id::text <> lower(v_supplier_id_text) then
      raise exception 'Invalid supplier metadata';
    end if;
  end if;

  if new.event_name = 'product_view' and new.product_id is null then
    raise exception 'product_id required';
  end if;

  if new.event_name = 'supplier_view' and new.supplier_id is null then
    raise exception 'supplier_id required';
  end if;

  if new.event_name in ('block_download', 'datasheet_download') then
    if new.product_id is null then
      raise exception 'product_id required';
    end if;

    v_file_id_text := nullif(trim(new.metadata->>'file_id'), '');
    if v_file_id_text is null
       or v_file_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      raise exception 'Valid file_id required';
    end if;

    v_expected_file_type := case
      when new.event_name = 'block_download' then 'block'
      else 'datasheet'
    end;

    if not exists (
      select 1
      from public.product_files pf
      where pf.id = v_file_id_text::uuid
        and pf.product_id = new.product_id
        and pf.is_available = true
        and coalesce(pf.file_type, 'block') = v_expected_file_type
    ) then
      raise exception 'Invalid file';
    end if;
  else
    new.metadata := new.metadata - 'file_id';
  end if;

  new.user_id := v_uid;
  select p.user_type into new.user_type
  from public.profiles p
  where p.id = v_uid;

  if new.user_type is null then
    raise exception 'Profile not found';
  end if;

  return new;
end;
$function$;

revoke execute on function public.set_usage_event_user_snapshot()
from public, anon, authenticated;


-- Restrictive policies intersect every existing permissive path, including future additions.
create policy launch_download_license on storage.objects as restrictive for select to authenticated
using (bucket_id not in ('product-files','product-datasheets') or exists (
  select 1 from public.product_files f join public.products p on p.id=f.product_id
  where f.storage_bucket=storage.objects.bucket_id and f.file_path=storage.objects.name
    and f.is_available and p.license_download is true and p.rights_confirmed is true
    and p.status='approved' and p.visibility='public'
) or (select public.get_my_role()) in ('admin','super_admin'));
-- Supplier self-service is deferred: zero writable capacity for deferred document buckets.
drop policy if exists docs_owner_upload on storage.objects;
create policy launch_deferred_documents_insert on storage.objects as restrictive for insert to authenticated
with check (bucket_id not in ('supplier-documents','ownership-proofs'));
create policy launch_deferred_documents_update on storage.objects as restrictive for update to authenticated
using (bucket_id not in ('supplier-documents','ownership-proofs'))
with check (bucket_id not in ('supplier-documents','ownership-proofs'));
commit;
